// Netlify Functions v2 adapter. Thin: no logic. NOT deployed by anyone yet (studio/README.md lists the manual steps).
// Place/bundle this file as a Netlify Function; the platform serves it at /api/studio/* and passes `context.ip`.
// STUDIO_BASE_PATH must be /api/studio. The schema file is generated by unit A (npm run studio:schema).
import schema from "../../schema/studio-schema.json" with { type: "json" };
import api from "../boot.js";

let handler = null;

export default async (req, context) => {
  if (!handler) handler = api.boot(Netlify.env.toObject(), { schema });
  const headers = new Headers(req.headers);
  headers.delete("x-studio-client-ip");
  headers.set("x-studio-client-ip", (context && context.ip) || "unknown");
  return handler(new Request(req, { headers }));
};

export const config = { path: "/api/studio/*" };
